<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';import { RefreshCw, Search } from 'lucide-vue-next';import { api } from '../api';import OperationsMap from '../components/OperationsMap.vue';import PageHeader from '../components/PageHeader.vue';import { useSessionStore } from '../stores/session';import type { PageData } from '../types';
const session=useSessionStore(),loading=ref(false),error=ref(''),rows=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(''),enterpriseId=ref(''),vehicleId=ref(''),organizationId=ref(''),status=ref(''),dateRange=ref<[string,string]|null>(null),drawer=ref(false),detailLoading=ref(false),detail=ref<any>(null);const options=reactive<any>({enterprises:[],vehicles:[],organizations:[]});const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');let timer:number|undefined;
async function loadOptions(){Object.assign(options,await api<any>('/operations/options'))}async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams({page:String(page.value),pageSize:'20'});if(q.value)p.set('q',q.value);if(enterpriseId.value)p.set('enterpriseId',enterpriseId.value);if(vehicleId.value)p.set('vehicleId',vehicleId.value);if(organizationId.value)p.set('organizationId',organizationId.value);if(status.value)p.set('status',status.value);if(dateRange.value){p.set('from',dateRange.value[0]);p.set('to',dateRange.value[1])}const data=await api<PageData<any>>(`/operations/records?${p}`);rows.value=data.items;total.value=data.total}catch(reason){error.value=reason instanceof Error?reason.message:'运行记录加载失败'}finally{loading.value=false}}watch([q,enterpriseId,vehicleId,organizationId,status,dateRange],()=>{page.value=1;clearTimeout(timer);timer=window.setTimeout(load,180)},{deep:true});watch(page,load);onMounted(()=>Promise.all([load(),loadOptions()]));async function open(row:any){drawer.value=true;detailLoading.value=true;try{detail.value=await api<any>(`/operations/records/${row.id}`)}finally{detailLoading.value=false}}const fmt=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'运行中';const statusText=(v:string)=>({RUNNING:'运行中',COMPLETED:'已完成',INTERRUPTED:'已中断'}as any)[v]??v;
</script>
<template><PageHeader :title="isEnterprise?'运行记录':'运行记录'" :description="isEnterprise?'查询本企业车辆全过程运行台账。':'按企业、车辆、时间、行政区和状态检索可回溯运行证据。'" :count="total"><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button></PageHeader><div class="table-toolbar records-toolbar"><el-input v-model="q" :prefix-icon="Search" clearable placeholder="搜索记录号或车辆" aria-label="搜索运行记录"/><el-select v-if="!isEnterprise" v-model="enterpriseId" clearable filterable placeholder="全部企业"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-model="vehicleId" clearable filterable placeholder="全部车辆"><el-option v-for="item in options.vehicles" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-if="!isEnterprise" v-model="organizationId" clearable placeholder="全部行政区"><el-option v-for="item in options.organizations" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-model="status" clearable placeholder="全部状态"><el-option label="运行中" value="RUNNING"/><el-option label="已完成" value="COMPLETED"/><el-option label="已中断" value="INTERRUPTED"/></el-select><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/></div><div v-if="error" class="error-state"><strong>运行记录暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><template v-else><el-table v-loading="loading" :data="rows" row-key="id" empty-text="暂无符合条件的运行记录"><el-table-column label="运行记录" min-width="185"><template #default="{row}"><button class="table-link" @click="open(row)"><strong>{{row.businessNo}}</strong><span>{{row._count.trackPoints}} 个轨迹点</span></button></template></el-table-column><el-table-column label="车辆" min-width="170"><template #default="{row}"><div class="identity-cell"><strong>{{row.vehicle.name}}</strong><span>{{row.vehicle.businessNo}}</span></div></template></el-table-column><el-table-column v-if="!isEnterprise" label="企业 / 行政区" min-width="220"><template #default="{row}"><div class="identity-cell"><strong>{{row.enterprise.name}}</strong><span>{{row.organization.name}}</span></div></template></el-table-column><el-table-column label="开始 / 结束" min-width="205"><template #default="{row}"><div class="identity-cell"><strong>{{fmt(row.startedAt)}}</strong><span>{{fmt(row.endedAt)}}</span></div></template></el-table-column><el-table-column label="运行区域" min-width="170"><template #default="{row}">{{row.region?.name||'未关联'}}</template></el-table-column><el-table-column label="里程 / 均速" width="135"><template #default="{row}">{{row.mileage}} km<br><span class="cell-meta">{{row.avgSpeed}} km/h</span></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag size="small" :type="row.status==='RUNNING'?'primary':row.status==='COMPLETED'?'success':'warning'">{{statusText(row.status)}}</el-tag></template></el-table-column></el-table><div class="pagination-row"><span>当前显示 {{rows.length}} / {{total}}</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next"/></div></template>
  <el-drawer v-model="drawer" size="860px" destroy-on-close><template #header><div class="archive-drawer-title"><div><span>{{detail?.businessNo}}</span><h2>运行记录详情</h2></div><el-tag v-if="detail" :type="detail.status==='COMPLETED'?'success':'warning'">{{statusText(detail.status)}}</el-tag></div></template><div v-loading="detailLoading"><template v-if="detail"><div class="record-summary"><div><span>运行车辆</span><strong>{{detail.vehicle.name}}</strong><small>{{detail.vehicle.businessNo}}</small></div><div><span>运行时段</span><strong>{{detail.durationMinutes}} 分钟</strong><small>{{fmt(detail.startedAt)}} — {{fmt(detail.endedAt)}}</small></div><div><span>运行质量</span><strong>{{detail.mileage}} km</strong><small>自动驾驶 {{detail.autonomousMiles}} km · 接管 {{detail.manualTakeovers}} 次</small></div></div><OperationsMap mode="trajectory" :track="detail.trackPoints" height="420px"/><dl class="detail-grid"><div><dt>起点</dt><dd>{{detail.startAddress||'—'}}</dd></div><div><dt>终点</dt><dd>{{detail.endAddress||'—'}}</dd></div><div><dt>所属企业</dt><dd>{{detail.enterprise.name}}</dd></div><div><dt>运行区域</dt><dd>{{detail.region?.name||'未关联'}}</dd></div><div><dt>平均 / 最高速度</dt><dd>{{detail.avgSpeed}} / {{detail.maxSpeed}} km/h</dd></div><div><dt>耗电量</dt><dd>{{detail.energyUsed}} kWh</dd></div></dl></template></div></el-drawer>
</template>
